#include "key_operation.h"
const QcaNativeScan*qca_scan_native_view(void);
static int apart(const void*a,unsigned n,const void*b,unsigned m){return a&&b&&(uintptr_t)a<=UINTPTR_MAX-n&&(uintptr_t)b<=UINTPTR_MAX-m&&((uintptr_t)a+n<=(uintptr_t)b||(uintptr_t)b+m<=(uintptr_t)a);}
void qsk_revoke(QsgKeyOp*s,unsigned reason){if(!s)return;s->phase=QSK_FAULT;if(s->pn)qpn_revoke(s->pn,s->epoch);if(s->glue)qsg_revoke(s->glue,reason);/* No CE halt, refund or invented all47 stop. */}
static int valid(QsgKeyOp*s,uint64_t now){return s&&s->glue&&s->pn&&s->tx&&s->phase&&s->phase!=QSK_FAULT&&now>=s->last&&(s->phase==QSK_CONFIRMED||now<=s->deadline)&&s->epoch==s->glue->epoch&&s->epoch==s->pn->epoch&&s->epoch==s->tx->epoch&&!s->pn->quarantined&&!s->glue->fault&&!s->glue->station->quarantined&&s->tx->radio==s->glue->data->radio;}
int qsk_begin(QsgKeyOp*s,QsgNative*g,QcaPersistentTx*t,QpnLedger*pn,unsigned index,const uint8_t*key,unsigned bytes,const uint8_t*rsc,unsigned rsc_bytes,uint64_t now){if(!s||s->phase||!g||!t||!pn||!key||bytes!=16||index>3||!now||now>UINT64_MAX-3000000||(rsc_bytes!=0&&rsc_bytes!=6)||(index&&rsc_bytes!=6)||(rsc_bytes&&!rsc)||!apart(s,sizeof(*s),g,sizeof(*g))||!apart(s,sizeof(*s),t,sizeof(*t))||!apart(s,sizeof(*s),pn,sizeof(*pn))||!apart(s,sizeof(*s),key,bytes)||(rsc_bytes&&!apart(s,sizeof(*s),rsc,rsc_bytes))||g->fault||!g->station||g->mgmt.phase!=STX_DONE||!g->station->associated||!g->station->mapped||g->station->pending||pn->pending||pn->key[index].attempted||pn->quarantined||g->epoch!=pn->epoch||g->station->peer_id!=pn->peer_id||t->phase!=QCA_TX_IDLE||!g->data||t->radio!=g->data->radio||t->epoch!=g->epoch||t->radio->rx.completed>UINT32_MAX)return 0;
 const QcaNativeScan*capture=qca_scan_native_view();if(!capture||capture->radio!=g->data->radio||capture->epoch!=g->epoch||capture->phase!=QCA_NATIVE_SCAN_LIVE_DONE||t!=&capture->tx)return 0;
 uint8_t command[160];/* Primary WMI generator has no RX sequence args. Actual
  * nonzero initial RSC is preserved in the joined host ledger, never discarded. */
 unsigned n=sta_wmi_key(command,sizeof command,&g->mgmt.bss,index,key,bytes,0,0);if(!n)return 0;uint32_t request=0;int rc=qca_tx_submit(t,command,n,now,3000000,&request);for(unsigned j=0;j<sizeof command;j++)((volatile uint8_t*)command)[j]=0;if(rc!=1||!request)return 0;
 QsgKeyOp v={0};v.glue=g;v.tx=t;v.pn=pn;v.epoch=g->epoch;v.last=now;v.deadline=now+3000000;v.request=request;v.phase=QSK_QUEUED;v.index=(uint8_t)index;v.rsc_bytes=rsc_bytes;for(unsigned j=0;j<rsc_bytes;j++)v.rsc[j]=rsc[j];*s=v;return 1;}
int qsk_poll(QsgKeyOp*s,uint64_t now){if(!valid(s,now)){qsk_revoke(s,40);return -1;}s->last=now;if(s->phase==QSK_CONFIRMED)return 1;uint64_t before=s->tx->radio->rx.completed;int rc=qca_tx_poll(s->tx,now);if(rc<0||before>UINT32_MAX){qsk_revoke(s,41);return -1;}
 if(s->phase==QSK_QUEUED&&(s->tx->phase==QCA_TX_POSTED||s->tx->phase==QCA_TX_DMA_DONE)){if(!s->tx->cookie||s->tx->request!=s->request||!qpn_key_posted(s->pn,s->epoch,s->index,s->rsc,s->rsc_bytes,(uint32_t)before,s->tx->cookie)||!sta_key_posted(s->glue->station,s->epoch,s->index==0,s->index,(uint32_t)before,s->tx->cookie)){qsk_revoke(s,42);return -1;}s->pub_floor=(uint32_t)before;s->pub_cookie=s->tx->cookie;s->phase=QSK_POSTED;}
 if(s->tx->phase==QCA_TX_DMA_DONE){if(s->tx->request!=s->request||s->tx->cookie!=s->pub_cookie||!s->tx->completed){qsk_revoke(s,47);return -1;}s->dma_serial=s->tx->completed;s->dma_seen=1;}
 if(s->phase==QSK_POSTED&&s->dma_seen&&s->sec_seen){if(!qca_tx_retire(s->tx,s->request)){qsk_revoke(s,43);return -1;}QcaInitAdapter*a=s->tx->radio->startup->operating->boot->board->setup->read.full.adapter;QcaCeRing*ring=&a->channels.rings[3];if(ring->read!=ring->write||ring->write!=ring->published||a->channels.buffers[7].bytes!=4096||!a->channels.buffers[7].host){qsk_revoke(s,46);return -1;}for(unsigned j=0;j<sizeof(s->tx->frame);j++)((volatile uint8_t*)s->tx->frame)[j]=0;for(unsigned j=0;j<4096;j++)((volatile uint8_t*)a->channels.buffers[7].host)[j]=0;s->phase=QSK_CONFIRMED;return 1;}return 0;}
int qsk_receive(QsgKeyOp*s,const QcaRxEvent*e,uint64_t now){if(!valid(s,now)||!e||s->phase!=QSK_POSTED||s->sec_seen||!apart(s,sizeof(*s),e,sizeof(*e))||e->completion>s->tx->radio->rx.completed){if(s&&e&&apart(s,sizeof(*s),e,sizeof(*e))&&e->raw_bytes<=2048)s->rejected=*e;qsk_revoke(s,44);return -1;}s->last=now;StaEvent event={0};if(sta_decode_htt_bound(e,&s->pn->htt,&s->pn->version,&event)!=1||event.kind!=STA_SEC_IND)return 0;if(!qpn_key_sec(s->pn,s->epoch,e)||!sta_observe(s->glue->station,s->epoch,&event)){s->rejected=*e;qsk_revoke(s,45);return -1;}s->sec_raw=*e;s->sec_seen=1;return 1;}
